// SPDX-License-Identifier: GPL-3.0
pragma solidity ^0.8.28;

/// Licenza "smart": il licenziatario deposita, l'oracle riporta l'uso,
/// chiunque può far pagare le royalty maturate (licenziante + quota a monte).
contract SmartLicense {
    address public immutable licensee;      // chi paga (es. produttore di smartphone)
    address public immutable licensor;      // chi incassa
    address public immutable upstream;      // titolare della tecnologia a monte
    address public immutable oracle;        // unico autorizzato a riportare l'uso
    uint256 public immutable weiPerSecond;  // tariffa
    uint256 public immutable upstreamPct;   // es. 10 (%)
    uint256 public owed;                    // royalty maturate e non ancora pagate

    event UsageReported(uint256 usageSeconds, uint256 amount);
    event RoyaltiesPaid(uint256 toLicensor, uint256 toUpstream);

    constructor(address _licensor, address _upstream, address _oracle,
                uint256 _weiPerSecond, uint256 _upstreamPct) payable {
        require(_upstreamPct <= 100, "pct > 100");
        licensee = msg.sender;
        licensor = _licensor;
        upstream = _upstream;
        oracle = _oracle;
        weiPerSecond = _weiPerSecond;
        upstreamPct = _upstreamPct;
    }

    function deposit() external payable {
        require(msg.sender == licensee, "only licensee");
    }

    function reportUsage(uint256 usageSeconds) external {
        require(msg.sender == oracle, "only oracle");
        uint256 amount = usageSeconds * weiPerSecond;
        owed += amount;
        emit UsageReported(usageSeconds, amount);
    }

    function settle() external {
        uint256 amount = owed <= address(this).balance ? owed : address(this).balance;
        owed -= amount;                                   // effects prima delle interactions
        uint256 up = amount * upstreamPct / 100;
        uint256 mine = amount - up;                       // l'arrotondamento resta al licensor
        (bool ok1, ) = upstream.call{value: up}("");
        (bool ok2, ) = licensor.call{value: mine}("");
        require(ok1 && ok2, "payment failed");
        emit RoyaltiesPaid(mine, up);
    }
}

import assert from "node:assert/strict";
import { describe, it } from "node:test";
import { network } from "hardhat";
import { parseEther, formatEther } from "viem";

describe("SmartLicense", async function () {
  const { viem, networkHelpers } = await network.create();
  const [manufacturer, smartphoneLicensor, torchOwner, oracle] = await viem.getWalletClients();
  const publicClient = await viem.getPublicClient();
  const RATE = 10n ** 12n; // wei per secondo di torcia accesa

  async function fixture() {
    const lic = await viem.deployContract("SmartLicense", [
      smartphoneLicensor.account.address, torchOwner.account.address,
      oracle.account.address, RATE, 10n,
    ], { value: parseEther("1") });
    return { lic };
  }

  it("uso riportato dall'oracle e pagamento 90/10", async function () {
    const { lic } = await networkHelpers.loadFixture(fixture);
    // intervallo 1: 1000 telefoni attivi, torcia accesa 2 s ciascuno; intervallo 2: 500 s totali
    const tx = await lic.write.reportUsage([2000n], { account: oracle.account });
    const r = await publicClient.getTransactionReceipt({ hash: tx });
    const tx2 = await lic.write.reportUsage([500n], { account: oracle.account });
    const r2 = await publicClient.getTransactionReceipt({ hash: tx2 });
    console.log("gas reportUsage: primo %d, successivo %d", r.gasUsed, r2.gasUsed);
    assert.equal(await lic.read.owed(), 2500n * RATE);
    await viem.assertions.balancesHaveChanged(lic.write.settle(), [
      { address: smartphoneLicensor.account.address, amount: 2250n * RATE },
      { address: torchOwner.account.address, amount: 250n * RATE },
      { address: lic.address, amount: -2500n * RATE },
    ]);
    console.log("pagato al licensor: %s ETH, a monte: %s ETH",
      formatEther(2250n * RATE), formatEther(250n * RATE));
  });

  it("solo l'oracle può riportare l'uso", async function () {
    const { lic } = await networkHelpers.loadFixture(fixture);
    await viem.assertions.revertWith(
      lic.write.reportUsage([1n], { account: manufacturer.account }), "only oracle");
  });

  it("se il deposito non basta si paga il possibile e il resto resta dovuto", async function () {
    const { lic } = await networkHelpers.loadFixture(fixture);
    await lic.write.reportUsage([3n * 10n ** 6n], { account: oracle.account }); // 3 ETH dovuti
    await lic.write.settle();
    console.log("ancora dovuto: %s ETH", formatEther(await lic.read.owed()));
    assert.equal(await lic.read.owed(), parseEther("2"));
  });
});

// SPDX-License-Identifier: GPL-3.0
pragma solidity ^0.8.28;

/// Variante "pull": settle() non invia ether, accredita i saldi;
/// ognuno ritira il proprio con withdraw().
contract SmartLicensePull {
    address public immutable licensee;
    address public immutable licensor;
    address public immutable upstream;
    address public immutable oracle;
    uint256 public immutable weiPerSecond;
    uint256 public immutable upstreamPct;
    uint256 public owed;
    uint256 public reserved;                     // già accreditato ma non ritirato
    mapping(address => uint256) public credit;

    constructor(address _licensor, address _upstream, address _oracle,
                uint256 _weiPerSecond, uint256 _upstreamPct) payable {
        require(_upstreamPct <= 100, "pct > 100");
        licensee = msg.sender;
        licensor = _licensor;
        upstream = _upstream;
        oracle = _oracle;
        weiPerSecond = _weiPerSecond;
        upstreamPct = _upstreamPct;
    }

    function deposit() external payable {
        require(msg.sender == licensee, "only licensee");
    }

    function reportUsage(uint256 usageSeconds) external {
        require(msg.sender == oracle, "only oracle");
        owed += usageSeconds * weiPerSecond;
    }

    function settle() external {
        uint256 free = address(this).balance - reserved;
        uint256 amount = owed <= free ? owed : free;
        owed -= amount;
        uint256 up = amount * upstreamPct / 100;
        credit[upstream] += up;
        credit[licensor] += amount - up;
        reserved += amount;
    }

    function withdraw() external {
        uint256 c = credit[msg.sender];
        require(c > 0, "nothing to withdraw");
        credit[msg.sender] = 0;                  // effects prima dell'interaction
        reserved -= c;
        (bool ok, ) = msg.sender.call{value: c}("");
        require(ok, "transfer failed");
    }
}

/// Destinatario che rifiuta ether: con il modello push blocca settle() per tutti.
contract Rejector {
    receive() external payable { revert("no thanks"); }
}

